        {
          id: "c2",
          label: "Standardize condition grades and data formats across all assessment contracts"
        },
        {
          id: "c3",
          label: "Schedule assessments by criticality so the highest risk assets are done first"
        },
        {
          id: "c4",
          label: "Quality check returned data before it enters the asset register"
        },
        {
          id: "c5",
          label: "Convert grades into remaining life and renewal timing in the asset plan"
        },
        {
          id: "c6",
          label: "Report assessment coverage and the condition trend to leadership annually"
        }
